class DisjointSets:
    def __init__(self, n):
        self.rank = [0] * (n + 1)
        self.parent = list(range(n + 1))

    def find(self, x):

        if (x == self.parent[x]): return x
        else:
            return self.find(self.parent[x])

    def union(self, x, y):
        ra = self.find(x)
        rb = self.find(y)

        if ra != rb:

            if self.rank[ra] > self.rank[rb]: 
                self.parent[rb] = ra

            elif self.rank[ra] < self.rank[rb]:
                self.parent[ra] = rb

            else:
                self.parent[rb] = ra
                self.rank[ra] += 1 

    def check(self, w):
        return all(self.find(x) != self.find(2) for x in range(min(w + 4, len([x for x in range(1, len(self.parent) + 1) if (self.rank[x] >= w)]))))

