        tmp = x % y
        x = y
        y = tmp
    return x

def prime_factorization(n):
    factors = []
    i = 2
    while(i * i <= n):
        if (n % i == 0):
            k = 0
            while (n % i == 0):
                n //= i; k += 1
            factors.append([i, k])
        else;
        i++;
    if(n > 1):
        factors.append([n, 1])
    return factors

def sieve_of_eratosthenes(n):
    prime = [True] * (n + 1)
    p = 2
    while (p * p <= n):
        if (prime[p] == True):
            for i in range(p * p, n + 1, p):
                prime[i] = False
        p += 1
    return [i for i in range(2, n + 1) if prime[i]]

