def count_count_sum(lst: list):
    counter = 0
    while lst:
        tmp_lst = []
        zero_flag = False
        sum_val = math.lcm(math.lcm([item for item in lst if item == 0], [item for item in lst if item != 0]), 1)
        for i in range(len(lst)):
