from collections import Counter

def solve(t):
    def can_sort(n, arr):
        m = len(arr)
        pq = []
        cnt = Counter(arr)

        for i in range(m):
            if cnt[i] % 2 != 0:
                num, val = arr[i], cnt[i]
                heapq.heappush(pq, (-val, num))

        i, j = 0, m - 1
        while i < j:
            val1, numi = heapq.heappop(pq)
            val2, numj = heapq.heappop(pq)

            if numi % 2 != 0 and numj % 2 != 0:
                return False
            numi -= 2 * abs(val1 - val2)
            while i < j and numi > 0:
                heapq.heappush(pq, (-abs(val1 - num[i]), num[i]))
                i += 1
            if not i < j:
                break
            numj -= 2 * abs(val2 - num[j])
            while i < j and numi <= 0:
                heapq.heappop(pq)
                j -= 1
            if not i < j:
                break

        return pq[0][0] == 0

