def solve(n):
    max_side = 0
    s = [n + i for i in range(1, n+1)]
    s.sort(reverse=True)
    block_size = (s[0] + 1) // 2 * i for i in range(int(math.sqrt(s[-1])) - 1, 1, -1)
    for size in block_size:
        if size + s[0] <= n and size * 4 == n:
            return min(size, max_side)
        elif size < n:
            remaining = n - (size + s[0])
            current_max = None
            for d in range(1, int(math.sqrt(remaining)) + 2):
                if remaining % 2 != 0 or remaining // 2 <= math.floor(d / 2) * ((2*d+1)//4):
                    continue
                temp = s[0] - (math.ceil(((d+1)//2) ** 2))
                for _ in range(2):
                    length = min(temp, d)
                    current_max = max(length * 2 + math.ceil(d / 2), current_max) if current_max is not None else length
            max_side = max(max_side, current_max)

    return int(max_side)

