def prime_factors(n: int) -> List[int]:
    factors = []
    i = 2
    while i * i <= n:
        if n % i == 0:
            count = 0
            while n % i == 0:
                n //= i
                count += 1
            factors.append(i)
            while count > 0:
                factors.append(i)
                count -= 1
        else:
            i += 1
    if n > 1:
        factors.append(n)
    return factors

