def solve(n, k, arr):
  dp = [[-1001000000] * (k + 2) for _ in range(1 << k)]

  def backtrack(idx, rem):
    if idx == n:
      return 0

    if rem == k:
      return max([arr[i] for i in [idx + j + 1 for j in range(k)]])

    if dp[rem][idx]:
      return dp[rem][idx]

    ans = -1001000000
    for next_idx in [idx + i % (k + 1) for i in range(len(arr))]:

      val = arr[next_idx] + backtrack(next_idx, rem + 1)

      ans = max(ans, arr[next_idx] if not val else val + binomial(k+1-rem)(k - ((i + next_idx) // k)))

    dp[rem][idx] = ans
    return ans

  sys.stdout.write(str(backtrack(0, 0)) + "\n")

