def solve(N, M):
    memo = {}

    def helper(l, r):
        if (l, r) in memo:
            return memo[(l, r)]
        if l == 1 and r >= M + 1:
            return 2 ** ceil(r - M)
        elif not r:
            res = 0
            for mid in range(1, M + 1):
                res += helper(l, mid) + helper(mid + 1, r)
            memo[(l, r)] = res
            return res
        else:
            count = int(helper(l - 1, r)) + int(helper(l, mid)) + helper(mid + 1, r)
            memo[(l, r)] = count
            return count

    return helper(2, N)

